61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    /**
112	     * Rejects an owner payload that is missing or blank in any of the required fields
113	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
114	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
115	     * value as present; this guard closes that gap so a blank in any required field is
116	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
117	     * the name of each offending field.
118	     */
119	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
120	        List<String> missing = new ArrayList<>();
121	        if (isBlank(ownerFieldsDto.getFirstName())) {
122	            missing.add("firstName");
123	        }
124	        if (isBlank(ownerFieldsDto.getLastName())) {
125	            missing.add("lastName");
126	        }
127	        if (isBlank(normalizedAddress)) {
128	            missing.add("address");
129	        }
130	        if (isBlank(ownerFieldsDto.getCity())) {
131	            missing.add("city");
132	        }
133	        if (isBlank(ownerFieldsDto.getTelephone())) {
134	            missing.add("telephone");
135	        }
136	        if (!missing.isEmpty()) {
137	            throw new MissingOwnerFieldsException(missing);
138	        }
139	    }
140	
141	    private static boolean isBlank(String value) {
142	        return value == null || value.isBlank();
143	    }
144	
145	    /**
146	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
147	     */
148	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
149	
150	    /**
151	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
152	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
153	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
154	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
155	     * stored as '+61412345678'. A value that cannot form a valid E.164 number is rejected via
156	     * {@link InvalidTelephoneException}, which the exception handler translates to a 400.
157	     */
158	    private static String normalizeTelephone(String telephone) {
159	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
160	        String e164;
161	        if (cleaned.startsWith("+")) {
162	            e164 = cleaned;
163	        } else {
164	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
165	            e164 = "+61" + national;
166	        }
167	        if (!E164_PATTERN.matcher(e164).matches()) {
168	            throw new InvalidTelephoneException(telephone);
169	        }
170	        return e164;
171	    }
172	
173	    /**
174	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
175	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
176	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
177	     */
178	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
179	
180	    /**
181	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
182	     * optional). When present it must be a syntactically valid address; a valid value is
183	     * lower-cased so it is stored and returned in canonical form. An invalid value is rejected via
184	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
185	     */
186	    private static String normalizeEmail(String email) {
187	        if (email == null) {
188	            return null;
189	        }
190	        if (!EMAIL_PATTERN.matcher(email).matches()) {
191	            throw new InvalidEmailException(email);
192	        }
193	        return email.toLowerCase(Locale.ROOT);
194	    }
195	
196	    /**
197	     * Rejects a create whose normalized telephone is already used by another owner. Each
198	     * existing owner's stored telephone is reduced to its E.164 form the same way {@code
199	     * normalizeTelephone} does, so the comparison is on the canonical E.164 value regardless of
200	     * the format each was originally entered in. An existing value that cannot form a valid E.164
201	     * number is skipped rather than colliding. A match is reported via
202	     * {@link DuplicateTelephoneException}, which the exception handler translates to a 409.
203	     */
204	    private void rejectDuplicateTelephone(String normalizedTelephone) {
205	        for (Owner existing : this.clinicService.findAllOwners()) {
206	            String existingE164;
207	            try {
208	                existingE164 = normalizeTelephone(existing.getTelephone());
209	            } catch (InvalidTelephoneException ex) {
210	                continue;
211	            }
212	            if (normalizedTelephone.equals(existingE164)) {
213	                throw new DuplicateTelephoneException(normalizedTelephone);
214	            }
215	        }
216	    }
217	
218	    /**
219	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
220	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
221	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
222	     * spacing do not defeat the duplicate-household check.
223	     */
224	    private static String collapse(String value) {
225	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
226	    }
227	
228	    /**
229	     * Normalizes an owner's address into a canonical form applied on every create: leading and
230	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
231	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
232	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
233	     * and returned, and is the form every address comparison (duplicate-household detection and the
234	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
235	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
236	     * so normalizing an already-normalized address is a no-op.
237	     */
238	    private static String normalizeAddress(String address) {
239	        if (address == null) {
240	            return "";
241	        }
242	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
243	        if (collapsed.isEmpty()) {
244	            return "";
245	        }
246	        String[] tokens = collapsed.split(" ");
247	        StringBuilder sb = new StringBuilder(collapsed.length());
248	        for (int i = 0; i < tokens.length; i++) {
249	            String token = tokens[i];
250	            switch (token) {
251	                case "ST" -> token = "STREET";
252	                case "RD" -> token = "ROAD";
253	                case "AVE" -> token = "AVENUE";
254	                default -> {
255	                }
256	            }
257	            if (i > 0) {
258	                sb.append(' ');
259	            }
260	            sb.append(token);
261	        }
262	        return sb.toString();
263	    }
264	
265	    /**
266	     * Rejects a create that would place a second owner in the same household as an existing one -
267	     * i.e. another owner already has the same {@code lastName} and the same {@code address},
268	     * compared case-insensitively with collapsed whitespace. The caller can opt in to sharing a
269	     * household by setting {@code sharesHousehold} true, in which case this check is skipped. A
270	     * match is reported via {@link DuplicateHouseholdException}, which the exception handler
271	     * translates to a 409.
272	     */
273	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
274	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
275	            return;
276	        }
277	        String lastName = collapse(ownerFieldsDto.getLastName());
278	        for (Owner existing : this.clinicService.findAllOwners()) {
279	            if (lastName.equals(collapse(existing.getLastName()))
280	                && normalizedAddress.equals(normalizeAddress(existing.getAddress()))) {
281	                throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
282	            }
283	        }
284	    }
285	
286	    /**
287	     * Builds the {@code customerCode} for a newly created owner, formatted {@code '<LAST3>-<NNNN>'}
288	     * where {@code LAST3} is the upper-cased first three letters of {@code lastName} and {@code NNNN}
289	     * is a global 4-digit zero-padded sequence equal to one more than the current number of owners
290	     * (e.g. {@code 'SMI-0007'}).
291	     */
292	    private String nextCustomerCode(String lastName) {
293	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
294	        int sequence = this.clinicService.findAllOwners().size() + 1;
295	        return String.format("%s-%04d", last3, sequence);
296	    }
297	
298	    /**
299	     * Builds the {@code membershipNumber} for a newly created owner, formatted
300	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
301	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}).
302	     */
303	    private static String membershipNumberFor(String customerCode, LocalDate registrationDate) {
304	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
305	    }
306	
307	    /**
308	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
309	     * {@code address} - the same pair used to detect a shared household. Because it is a pure
310	     * function of that pair (upper-case hex of SHA-256 over the two collapsed values), every owner
311	     * in the same household - whether created first or joining later via {@code sharesHousehold} -
312	     * receives the identical, non-blank identifier without needing to read any other owner's value.
313	     */
314	    private static String householdIdFor(String lastName, String address) {
315	        String key = collapse(lastName) + "\n" + normalizeAddress(address);
316	        try {
317	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
318	            StringBuilder sb = new StringBuilder(32);
319	            for (int i = 0; i < 8; i++) {
320	                sb.append(String.format("%02X", digest[i]));
321	            }
322	            return sb.toString();
323	        } catch (NoSuchAlgorithmException ex) {
324	            throw new IllegalStateException("SHA-256 not available", ex);
325	        }
326	    }
327	
328	    /**
329	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
330	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
331	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
332	     */
333	    private int countNamesakes(String firstName, String lastName) {
334	        int count = 0;
335	        for (Owner existing : this.clinicService.findAllOwners()) {
336	            if (firstName.equalsIgnoreCase(existing.getFirstName())
337	                && lastName.equalsIgnoreCase(existing.getLastName())) {
338	                count++;
339	            }
340	        }
341	        return count;
342	    }
343	
344	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
345	    @Override
346	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
347	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
348	        rejectMissingOrBlankFields(ownerFieldsDto, normalizedAddress);
349	        rejectDuplicateHousehold(ownerFieldsDto, normalizedAddress);
350	        HttpHeaders headers = new HttpHeaders();
351	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
352	        owner.setAddress(normalizedAddress);
353	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
354	        rejectDuplicateTelephone(normalizedTelephone);
355	        owner.setTelephone(normalizedTelephone);
356	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
357	        if (owner.getRegistrationDate() == null) {
358	            owner.setRegistrationDate(LocalDate.now());
359	        }
360	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
361	        owner.setMembershipNumber(membershipNumberFor(owner.getCustomerCode(), owner.getRegistrationDate()));
362	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getAddress()));
363	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
364	        this.clinicService.saveOwner(owner);
365	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
366	        headers.setLocation(UriComponentsBuilder.newInstance()
367	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
368	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
369	    }
370	
371	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
372	    @Override
373	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
374	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
375	        if (currentOwner == null) {
376	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
377	        }
378	        currentOwner.setAddress(ownerFieldsDto.getAddress());
379	        currentOwner.setCity(ownerFieldsDto.getCity());
380	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
381	        currentOwner.setLastName(ownerFieldsDto.getLastName());
382	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
383	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
384	        this.clinicService.saveOwner(currentOwner);
385	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
386	    }
387	
388	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
389	    @Transactional
390	    @Override
391	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
392	        Owner owner = this.clinicService.findOwnerById(ownerId);
393	        if (owner == null) {
394	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
395	        }
396	        this.clinicService.deleteOwner(owner);
397	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
398	    }
399	
400	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
401	    @Override
402	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
403	        Owner owner = this.clinicService.findOwnerById(ownerId);
404	        if (owner == null) {
405	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
406	        }
407	        HttpHeaders headers = new HttpHeaders();
408	        Pet pet = petMapper.toPet(petFieldsDto);
409	        owner.setId(ownerId);
410	        pet.setOwner(owner);
411	        pet.getType().setName(null);
412	        this.clinicService.savePet(pet);
413	        PetDto petDto = petMapper.toPetDto(pet);
414	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
415	            .buildAndExpand(pet.getId()).toUri());
416	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
417	    }
418	
419	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
420	    @Override
421	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
422	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
423	        if (currentOwner != null) {
424	            Pet currentPet = this.clinicService.findPetById(petId);
425	            if (currentPet != null) {
426	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
427	                currentPet.setName(petFieldsDto.getName());
428	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
429	                this.clinicService.savePet(currentPet);
430	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
431	            }
432	        }
433	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
434	    }
435	
436	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
437	    @Override
438	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
439	        HttpHeaders headers = new HttpHeaders();
440	        Visit visit = visitMapper.toVisit(visitFieldsDto);
441	        Pet pet = new Pet();
442	        pet.setId(petId);
443	        visit.setPet(pet);
444	        this.clinicService.saveVisit(visit);
445	        VisitDto visitDto = visitMapper.toVisitDto(visit);
446	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
447	            .buildAndExpand(visit.getId()).toUri());
448	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
449	    }
450	
451	
452	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
453	    @Override
454	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
455	        Owner owner = this.clinicService.findOwnerById(ownerId);
456	        if (owner != null) {
457	            Pet pet = owner.getPet(petId);
458	            if (pet != null) {
459	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
460	            }
461	        }
462	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
463	    }
464	}
